"    // 8. Fetch Additional Charges
    try {
      const chargesRes = await posService.getAdditionalCharges(outletIdToPass);
      setAvailableCharges((chargesRes.data || []).filter(c => c.is_active));
      localStorage.setItem('pos_additional_charges', JSON.stringify(chargesRes.data || []));
    } catch (e) {
      console.warn("initApp - Failed to fetch additional charges:", e);
    }

    // 9. Fetch Orders
    try {
      await fetchOrdersForMode(receiptsDateMode);
    } catch (err) {
      console.warn("initApp - Failed to load orders from backend:", err);
    }

    // 10. Fetch CRM Customers
    try {
      const custRes = await posService.getCustomers();
      if (custRes.data && Array.isArray(custRes.data)) {
        const customersMap = {};
        custRes.data.forEach(c => {
          customersMap[c.phone] = {
            name: c.name,
            phone: c.phone,
            address: c.address,
            points: Number(c.points) || 0,
            orders: Number(c.orders) || 0,
            totalSpent: Number(c.total_spent) || 0,
            balance: Number(c.balance) || 0
          };
        });
        setCustomerDb(customersMap);
        localStorage.setItem('pos_customer_db', JSON.stringify(customersMap));
      }
    } catch (e) {
      console.warn("initApp - Failed to load customers from backend:", e);
    }

    // 11. Fetch Dashboard Stats
    try {
      await fetchDashboardStatsFromServer();
    } catch (e) {
      console.warn("initApp - Failed to load dashboard stats:", e);
    }
  };

